agent_detail.agent_sql:
SELECT ?team_fifa_api_id WHERE {
  ?ta a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/team_fifa_api_id> ?team_fifa_api_id ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplayspeed> ?speed .
  FILTER (xsd:decimal(?speed) > 50 && xsd:decimal(?speed) < 60)
}

SELECT ?buildupplayspeed WHERE {
  ?ta a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplayspeed> ?buildupplayspeed .
}
ORDER BY DESC(xsd:integer(?buildupplayspeed))
LIMIT 4

SELECT ?name WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> ?season ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/home_team_goal> ?hg ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/away_team_goal> ?ag ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?l .
  ?l <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> ?name .
  FILTER(CONTAINS(?season, "2016"))
  FILTER(?hg = ?ag)
}
GROUP BY ?name
ORDER BY DESC(COUNT(?m))
LIMIT 1

SELECT ?leagueName (COUNT(?m) AS ?matchCount) WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?l .
  ?l <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> ?leagueName .
}
GROUP BY ?leagueName
ORDER BY DESC(?matchCount)
LIMIT 1

SELECT ?name WHERE {
  {
    SELECT ?name (SUM(?hg) + SUM(?ag) AS ?total)
    WHERE {
      ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
         <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?l ;
         <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/home_team_goal> ?hg ;
         <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/away_team_goal> ?ag ;
         <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> ?s .
      ?l a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League> ;
         <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> ?name .
      FILTER(CONTAINS(STR(?s), "2016"))
    }
    GROUP BY ?name
  }
}
ORDER BY DESC(?total)
LIMIT 1

SELECT ?team_long_name WHERE {
  SELECT ?team_long_name (COUNT(?m) AS ?wins) WHERE {
    ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/away_team_goal> ?ag ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/home_team_goal> ?hg ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/away_team_api_id> ?ateam ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> ?season ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?league .
    ?league <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> "Scotland Premier League" .
    ?team a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team> ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team/team_api_id> ?ateam ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team/team_long_name> ?team_long_name .
    FILTER(xsd:integer(?ag) > xsd:integer(?hg))
    FILTER(STRSTARTS(STR(?season), "2010"))
  }
  GROUP BY ?team_long_name
  ORDER BY DESC(?wins)
  LIMIT 1
}

SELECT (AVG(?longShots) AS ?avgLongShots) WHERE {
  ?player a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
    <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> "Ahmed Samir Farag" ;
    <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?attr a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
    <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
    <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/long_shots> ?longShots .
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?birthday .
  BIND(SUBSTR(STR(?birthday), 1, 4) AS ?year)
  BIND(SUBSTR(STR(?birthday), 6, 2) AS ?month)
  FILTER(?year = "1970" && ?month = "10")
}

SELECT (AVG(?goal) AS ?avgHomeGoal)
WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> "2010/2011" ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/home_team_goal> ?goal ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasCountry> ?c .
  ?c a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Country> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Country/name> "Poland" .
}

SELECT (AVG(?rating) AS ?avgRating) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?paid ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/height> ?height .
  ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?paid ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?date .
  FILTER(xsd:decimal(?height) > 170)
  BIND(SUBSTR(STR(?date),1,4) AS ?year)
  FILTER(?year >= "2010" && ?year <= "2015")
}

SELECT (?avg1 - ?avg2 AS ?diff) WHERE {
  {
    SELECT (AVG(?bc1) AS ?avg1) WHERE {
      ?p1 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> "Abdou Diallo" ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id1 .
      ?pa1 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id1 ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc1 .
    }
  }
  {
    SELECT (AVG(?bc2) AS ?avg2) WHERE {
      ?p2 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> "Aaron Appindangoye" ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id2 .
      ?pa2 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id2 ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc2 .
    }
  }
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?bday .
  FILTER(?player_name IN ("Aaron Lennon","Abdelaziz Barrada"))
}
ORDER BY ?bday
LIMIT 1

SELECT ?player_name
WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/height> ?height .
}
ORDER BY DESC(xsd:decimal(?height))
LIMIT 1

SELECT DISTINCT ?team_long_name WHERE {
  {
    SELECT (AVG(?bpp) AS ?avgBpp) WHERE {
      ?ta a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes> ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?d ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplaypassing> ?bpp .
      FILTER(STRSTARTS(STR(?d), "2012"))
    }
  }
  ?ta2 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes> ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?d2 ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplaypassing> ?bpp2 ;
       <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/TeamAttributes/team_api_id> ?tid .
  FILTER(STRSTARTS(STR(?d2), "2012"))
  FILTER(xsd:decimal(?bpp2) > ?avgBpp)
  ?team a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team> ;
        <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team/team_api_id> ?tid ;
        <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Team/team_long_name> ?team_long_name .
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> "left" ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/attacking_work_rate> "low" .
}

SELECT ?age WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?papi ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?bday .
  ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?papi ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/sprint_speed> ?ss ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?d .
  FILTER(xsd:integer(?ss) >= 97)
  BIND(SUBSTR(STR(?d),1,4) AS ?year)
  FILTER(?year >= "2013" && ?year <= "2015")
  BIND(SUBSTR(STR(?bday),1,4) AS ?byear)
  BIND((YEAR(NOW()) - xsd:integer(?byear)) AS ?age)
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/height> ?height ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?paid .
  FILTER(xsd:decimal(?height) > 180)
  ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?paid ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/heading_accuracy> ?heading .
}
GROUP BY ?player_name
ORDER BY DESC(AVG(?heading))
LIMIT 10

SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?bday ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/player_api_id> ?papi .
  ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?papi ;
      <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/attacking_work_rate> ?awr .
  BIND(xsd:integer(SUBSTR(STR(?bday),1,4)) AS ?year)
  FILTER(?year < 1986)
  FILTER(LCASE(?awr) = "low")
}

SELECT (xsd:decimal(?left) * 100.0 / xsd:decimal(?total) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?p) AS ?total) WHERE {
      ?pa a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
          <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/hasPlayer> ?p .
      ?p <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?bday .
      BIND(SUBSTR(STR(?bday),1,4) AS ?year)
      FILTER(xsd:integer(?year) >= 1987 && xsd:integer(?year) <= 1992)
    }
  }
  {
    SELECT (COUNT(?p2) AS ?left) WHERE {
      ?pa2 a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/hasPlayer> ?p2 ;
           <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> "left" .
      ?p2 <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Player/birthday> ?bday2 .
      BIND(SUBSTR(STR(?bday2),1,4) AS ?year2)
      FILTER(xsd:integer(?year2) >= 1987 && xsd:integer(?year2) <= 1992)
    }
  }
}

SELECT (COUNT(*) AS ?n) WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?l ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/date> ?d .
  ?l <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> "Belgium Jupiler League" .
  FILTER(STRSTARTS(STR(?d), "2009-04"))
}

SELECT ?name WHERE {
  ?l a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> ?name .
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/league_id> ?lid ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> ?season ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/home_team_goal> ?hg ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/away_team_goal> ?ag .
  ?l <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/id> ?lid .
  FILTER(?season = "2009/2010")
}
GROUP BY ?name
HAVING (AVG(?hg) > AVG(?ag))

SELECT ?name WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/season> "2008/2009" ;
     <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/Match/hasLeague> ?l .
  ?l <http://bird-bird_european_football_2-ontology-20260809-233203/ontology/vkg-bird_european_football_2/League/name> ?name .
